      hu: ["Misszionáriusok és helyiek építették.", "Színes fagerendás mennyezetéről ismert.", "Egy kis dombon található.", "Fontos helyszín a vallási ünnepeken."],
      ro: ["Construită de misionari și localnici.", "Cunoscută pentru tavanul său colorat din lemn.", "Situată pe un mic deal.", "Importantă pentru sărbătorile religioase."],
